if len(sys.argv) > 1: P.update(json.load(open(sys.argv[1])))
async def one(prompt, c):
    g, prev, ans, pause, new, glue, writing = (*c, "")[:7]
    last = Req(1, "ask", prev, state="answered" if ans else "sent", answer=ans)
    r = await d.evaluate(input=listen.said(new, last, pause, False, writing), decisions={"c": Probability(prompt)}, conn_options=APIConnectOptions(max_retry=2, timeout=15))
    return r.results["c"].value
async def main():
    sem = asyncio.Semaphore(6)
    async def lim(p, c):
        async with sem: return await one(p, c)
    for name, prompt in P.items():
        ps = await asyncio.gather(*(lim(prompt, c) for c in C))
        ok = [(p >= listen.SURE) == c[5] for p, c in zip(ps, C)]
        by = {}
        for c, o in zip(C, ok): by.setdefault(c[0][0], []).append(o)
        margin = min((p - listen.SURE) if c[5] else (listen.SURE - p) for p, c in zip(ps, C))
        print(f"{name:12} {sum(ok)}/{len(C)} запас {margin:+.2f} | " + ' '.join(f"{g}:{sum(v)}/{len(v)}" for g, v in by.items()) + " | " + ' '.join(f"{p:.2f}{'' if o else '✗'}" for p, o in zip(ps, ok)))
asyncio.run(main())
